package native
import("bytes";"encoding/json";"os";"strings";"testing")
func TestOriginalObservatoryOverlay(t *testing.T){s,e:=New(2030);if e!=nil{t.Fatal(e)};defer s.Close();data,e:=os.ReadFile("../../tests/fixtures/original-observatory-overlay/setup.ndjson");if e!=nil{t.Fatal(e)};for _,line:=range strings.Split(strings.TrimSpace(string(data)),"\n"){if _,e=s.CommandRaw([]byte(line));e!=nil{t.Fatal(e)}};if _,e=s.CommandRaw([]byte(`{"op":"observatory-overlay","kind":"warp"}`));e!=nil{t.Fatal(e)};raw,e:=s.InfoComplete();if e!=nil{t.Fatal(e)};var info map[string]any;if e=json.Unmarshal(raw,&info);e!=nil{t.Fatal(e)};if info["observatoryOverlay"].(map[string]any)["kind"]!="warp"{t.Fatal(info["observatoryOverlay"])};before,_:=s.Snapshot();if _,e=s.CommandRaw([]byte(`{"op":"observatory-overlay","fallMs":4001}`));e==nil{t.Fatal("invalid value accepted")};after,_:=s.Snapshot();if !bytes.Equal(before,after){t.Fatal("rejected patch mutated state")}}
